<div id="consent-banner" role="dialog" aria-label="Cookie consent" hidden>
	<p>We use analytics cookies only if you accept. <a href="/privacy/">Privacy notice</a></p>
	<button type="button" class="consent-btn" data-consent="granted">Accept all</button>
	<button type="button" class="consent-btn" data-consent="denied">Reject all</button>
</div>
<button type="button" id="consent-reopen" class="consent-link" hidden>Cookie settings</button>

{/* A plain script (not is:inline): Astro bundles it and security.csp adds its hash, so no nonce is needed. */}
<script>
	type Choice = 'granted' | 'denied';
	const TAG_ID = 'G-XXXXXXXXXX'; // your Google tag ID
	const TYPES = ['ad_storage', 'analytics_storage', 'ad_user_data', 'ad_personalization'];
	const w = window as unknown as { dataLayer?: unknown[] };
	w.dataLayer = w.dataLayer || [];
	// Google requires the Arguments object itself on the dataLayer, not an array.
	function gtag(..._args: unknown[]) {
		w.dataLayer!.push(arguments);
	}
	function state(value: Choice) {
		return Object.fromEntries(TYPES.map((type) => [type, value]));
	}
	gtag('consent', 'default', state('denied')); // before any Google tag request

	function stored(): Choice | null {
		const match = document.cookie.match(/(?:^|; )consent=(granted|denied)/);
		return match ? (match[1] as Choice) : null;
	}
	function store(value: Choice) {
		// `consent` is an essential cookie: list it in the project's essentialCookies.
		document.cookie = `consent=${value}; Max-Age=31536000; Path=/; SameSite=Lax${location.protocol === 'https:' ? '; Secure' : ''}`;
	}
	let loaded = false;
	function loadTag() {
		if (loaded) return;
		loaded = true;
		const script = document.createElement('script');
		script.async = true;
		script.src = `https://www.googletagmanager.com/gtag/js?id=${encodeURIComponent(TAG_ID)}`; // trusted via 'strict-dynamic'
		document.head.appendChild(script);
		gtag('js', new Date());
		gtag('config', TAG_ID);
	}
	function apply(value: Choice) {
		gtag('consent', 'update', state(value));
		if (value === 'granted') loadTag(); // only after Accept: no Google host is contacted before
	}

	const banner = document.getElementById('consent-banner');
	const reopen = document.getElementById('consent-reopen');
	function show(on: boolean) {
		if (banner) banner.hidden = !on;
		if (reopen) reopen.hidden = on;
	}
	document.addEventListener('click', (event) => {
		const target = event.target as Element | null;
		const choice = target?.closest('[data-consent]');
		if (choice) {
			const value = choice.getAttribute('data-consent') as Choice;
			store(value);
			apply(value);
			show(false);
		} else if (target?.closest('#consent-reopen')) show(true);
	});

	const prior = stored();
	if (prior) {
		apply(prior);
		show(false);
	} else {
		if ((navigator as Navigator & { globalPrivacyControl?: boolean }).globalPrivacyControl === true) apply('denied');
		show(true);
	}
</script>

<style>
