import Base from '../../layouts/Base.astro';

export const prerender = false; // looked up per request, so 404 / 503 are decided before the response starts

type Product = { slug: string; name: string };

// Replace with the project's data access. null = no such row; a throw = the backend is down.
async function findProduct(slug: string): Promise<Product | null> {
	const rows: Product[] = [{ slug: 'example', name: 'Example product' }];
	return rows.find((row) => row.slug === slug) ?? null;
}

const { slug = '' } = Astro.params;
// RTE-004: unknown or malformed params answer 404 (the rewrite keeps the 404 status and the 404 page).
if (!/^[a-z0-9][a-z0-9-]{0,79}$/.test(slug)) return Astro.rewrite('/404');

let product: Product | null = null;
let unavailable = false;
try {
	product = await findProduct(slug);
} catch (cause) {
	console.error(cause);
	unavailable = true;
	Astro.response.status = 503; // RTE-007: a dependency failure is a 5xx, never 404 or 200
}
if (!unavailable && !product) return Astro.rewrite('/404');
---

