import { defineMiddleware, sequence } from 'astro:middleware';

// RTE-004: retired paths with no successor answer 410 (rendered by src/pages/gone.astro).
const RETIRED = new Set(['/old-offer/']);
const gone = defineMiddleware(async (context, next) => {
	const response = await next();
	return response.status === 404 && RETIRED.has(context.url.pathname) ? context.rewrite('/gone/') : response;
});

// Add `gone` to the existing sequence(), e.g. sequence(gone, securityHeaders).
export const onRequest = sequence(gone);

