import Base from '../layouts/Base.astro';
import { getSecret } from 'astro:env/server';
import { limited } from '../lib/rate-limit';

export const prerender = false; // handles the POST itself, so it runs per request (needs an adapter)

// SEC-024: security.checkOrigin is true by default and answers cross-origin form POSTs on on-demand
// pages with 403 (Sec-Fetch-Site / Origin). Do not turn it off.

let error = '';
let values = { name: '', email: '', message: '' };

if (Astro.request.method === 'POST') {
	const form = await Astro.request.formData();
	values = {
		name: String(form.get('name') ?? '').trim(),
		email: String(form.get('email') ?? '').trim(),
		message: String(form.get('message') ?? '').trim()
	};
	const valid =
		values.name && values.name.length <= 100 && /^[^@\s]+@[^@\s]+\.[^@\s]+$/.test(values.email) &&
		values.email.length <= 254 && values.message && values.message.length <= 5000;

	if (limited(Astro.clientAddress)) {
		Astro.response.status = 429; // SEC-054
		error = 'Too many messages. Please try again later.';
	} else if (String(form.get('website') ?? '') !== '') {
		// SEC-055: honeypot. Bots fill the hidden field; answer like a success and do nothing.
		// (Alternative: Cloudflare Turnstile - read `cf-turnstile-response` and verify it server-side.)
		return Astro.redirect('/contact/thanks/', 303);
	} else if (!valid) {
		Astro.response.status = 400;
		error = 'Please check the fields and try again.';
	} else {
		try {
			// The one line the project replaces: webhook, email provider API or database insert.
			const url = getSecret('FORM_WEBHOOK_URL');
			if (!url) throw new Error('FORM_WEBHOOK_URL is not set');
			const res = await fetch(url, {
				method: 'POST',
				headers: { 'Content-Type': 'application/json' },
				body: JSON.stringify(values),
				signal: AbortSignal.timeout(8000)
			});
			if (!res.ok) throw new Error(`webhook answered ${res.status}`); // RES-008: no success without delivery
			return Astro.redirect('/contact/thanks/', 303);
		} catch (cause) {
			console.error('contact delivery failed', cause);
			Astro.response.status = 502;
			error = 'We could not send your message. Please try again later.';
		}
	}
}
---

<Base title="Contact">
	<main>
		<h1>Contact us</h1>
		{error && <p role="alert">{error}</p>}
		<form method="POST" action="/contact/">
			<label for="name">Name</label>
			<input id="name" name="name" autocomplete="name" required maxlength="100" value={values.name} />

			<label for="email">Email</label>
			<input id="email" name="email" type="email" autocomplete="email" required maxlength="254" value={values.email} />

			<label for="message">Message</label>
			<textarea id="message" name="message" required maxlength="5000">{values.message}</textarea>

			<!-- Honeypot: off-screen, not type=hidden, ignored by assistive tech and keyboard users -->
			<div class="trap" aria-hidden="true">
				<label for="website">Leave this empty</label>
				<input id="website" name="website" tabindex="-1" autocomplete="off" />
			</div>

			<p>By sending this form you agree to our <a href="/privacy/">privacy notice</a>.</p>
			<button type="submit">Send message</button>
		</form>
	</main>
</Base>

<style>
