// SEC-054 placeholder: in memory, per process. It must live in a module: page frontmatter runs again
// on every request, so a Map declared there would start empty each time. Use Redis or your edge for several instances.
const WINDOW_MS = 10 * 60_000;
const MAX_PER_WINDOW = 5;
const hits = new Map<string, number[]>();

export function limited(key: string): boolean {
	const now = Date.now();
	const recent = (hits.get(key) ?? []).filter((t) => now - t < WINDOW_MS);
	recent.push(now);
	hits.set(key, recent);
	return recent.length > MAX_PER_WINDOW;
}

Astro 6+ (security.csp is stable from Astro 6; on Astro 5 use `experimental: { csp: true }`). On-demand pages get a CSP header from Astro (script/style hashes plus 'strict-dynamic'); prerendered pages only get a <meta> tag, which cannot carry frame-ancestors, so the integration copies that policy into a `_headers` file (Netlify, Cloudflare Pages; convert for nginx/Apache). With 'strict-dynamic' a <script src> is blocked, hence the raised assetsInlineLimit (page scripts stay inline and hashed). Purely static site: drop `adapter` and src/middleware.ts.

