import { defineConfig } from 'astro/config';
import node from '@astrojs/node'; // only for on-demand pages; any adapter works
import sitemap from '@astrojs/sitemap';
import securityHeadersFile from './src/integrations/security-headers.mjs';

const production = process.env.DEPLOY_ENV === 'production'; // IDX-005: the only value that means production

export default defineConfig({
	site: process.env.SITE_URL ?? 'http://localhost:4321', // the canonical origin; set SITE_URL per environment
	trailingSlash: 'always', // matches build.format 'directory' (the default): /about/ -> about/index.html (URL-001)
	adapter: node({ mode: 'standalone' }),
	// With 'strict-dynamic' a parser-inserted <script src> is blocked (only hashed inline scripts are trusted), and Astro
	// emits a page script as a file once it exceeds this limit. Raise it so page scripts stay inline (and hashed).
	vite: { build: { assetsInlineLimit: 65536 } },
	integrations: [
		// Sitemap only in production; elsewhere no file exists, so /sitemap-index.xml is a 404 (IDX-005).
		production && sitemap({ filter: (page) => !/\/(api|account|gone|contact\/thanks)\//.test(page) }),
		securityHeadersFile()
	],
	security: {
		csp: {
			// Hashes of every inline script/style Astro emits; 'strict-dynamic' also trusts scripts those create.
			scriptDirective: { strictDynamic: true },
			directives: [
				"default-src 'self'",
				"img-src 'self' data:",
				"font-src 'self'",
				"connect-src 'self'",
				"object-src 'none'",
				"base-uri 'self'",
				"form-action 'self'"
			]
		}
	}
});

