import { defineMiddleware, sequence } from 'astro:middleware';

// Runs for on-demand pages and endpoints. Prerendered pages run it only at build time, where it can set
// nothing the host will send; their headers come from the _headers file the integration writes.
const securityHeaders = defineMiddleware(async (context, next) => {
	if (context.isPrerendered) return next();
	const response = await next();
	const out = new Response(response.body, response); // next() can return immutable headers
	out.headers.set('X-Content-Type-Options', 'nosniff');
	out.headers.set('Referrer-Policy', 'strict-origin-when-cross-origin');
	out.headers.set('Permissions-Policy', 'camera=(), microphone=(), geolocation=()');
	if (context.url.protocol === 'https:' || context.request.headers.get('x-forwarded-proto') === 'https') {
		out.headers.set('Strict-Transport-Security', 'max-age=63072000; includeSubDomains');
	}
	const csp = out.headers.get('content-security-policy');
	// security.csp sends the CSP header for on-demand pages; it has no frame-ancestors, so add it here.
	if (csp && !/frame-ancestors/.test(csp)) out.headers.set('Content-Security-Policy', `${csp.replace(/;\s*$/, '')}; frame-ancestors 'none'`);
	if ((out.headers.get('content-type') ?? '').startsWith('text/html') && !out.headers.has('cache-control')) {
		out.headers.set('Cache-Control', 'public, max-age=0, must-revalidate'); // PRF-008; use private, no-store for per-user pages
	}
	return out;
});

// Keep one sequence() for the whole app; other recipes add their middleware to it.
export const onRequest = sequence(securityHeaders);

