import fs from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';

// Prerendered pages are served by the host, not by Astro, so security.csp only reaches them as a
// <meta> tag - and a meta CSP cannot carry frame-ancestors. This writes the same policy (hashes and
// all) as a real header into `_headers` (Netlify, Cloudflare Pages; convert for nginx/Apache).
const GLOBAL = [
	'X-Content-Type-Options: nosniff',
	'Referrer-Policy: strict-origin-when-cross-origin',
	'Permissions-Policy: camera=(), microphone=(), geolocation=()',
	'Strict-Transport-Security: max-age=63072000; includeSubDomains'
];

function htmlFiles(dir) {
	return fs.readdirSync(dir, { withFileTypes: true }).flatMap((entry) => {
		const full = path.join(dir, entry.name);
		return entry.isDirectory() ? htmlFiles(full) : entry.name.endsWith('.html') ? [full] : [];
	});
}

export default function securityHeadersFile() {
	return {
		name: 'security-headers-file',
		hooks: {
			'astro:build:done': ({ dir, logger }) => {
				const root = fileURLToPath(dir);
				const blocks = [['/*', [...GLOBAL, ...(process.env.DEPLOY_ENV === 'production' ? [] : ['X-Robots-Tag: noindex, nofollow'])]]];
				blocks.push(['/_astro/*', ['Cache-Control: public, max-age=31536000, immutable']]); // PRF-008
				for (const file of htmlFiles(root)) {
					const html = fs.readFileSync(file, 'utf8');
					const meta = html.match(/<meta http-equiv="content-security-policy" content="([^"]*)"/i);
					if (!meta) continue; // on-demand pages get their CSP header from Astro at request time
					let csp = meta[1].replace(/&amp;/g, '&').replace(/&#39;|&apos;/g, "'").trim().replace(/;$/, '');
					if (!/frame-ancestors/.test(csp)) csp += "; frame-ancestors 'none'";
					const rel = path.relative(root, file).split(path.sep).join('/');
					const url = '/' + rel.replace(/(^|\/)index\.html$/, '$1');
					blocks.push([url, [`Content-Security-Policy: ${csp}`, 'Cache-Control: public, max-age=0, must-revalidate']]);
				}
				const text = blocks.map(([url, lines]) => `${url}\n${lines.map((l) => `  ${l}`).join('\n')}`).join('\n\n') + '\n';
				fs.writeFileSync(path.join(root, '_headers'), text);
				logger.info(`wrote _headers (${blocks.length - 2} pages)`);
			}
		}
	};
}

