import net from 'node:net';
import type { APIRoute } from 'astro';
import { getSecret } from 'astro:env/server';

export const prerender = false; // needs an adapter; must run per request

// Opens a TCP connection to DATABASE_URL's host:port (needs no driver); with a client, replace the
// body with `await db.query('SELECT 1')`. No DATABASE_URL = no dependency to check. Failure must reject.
async function checkDatabase(timeoutMs = 2000): Promise<void> {
	const databaseUrl = getSecret('DATABASE_URL');
	if (!databaseUrl) return;
	const url = new URL(databaseUrl);
	await new Promise<void>((resolve, reject) => {
		const socket = net.connect({ host: url.hostname, port: Number(url.port) || 5432 });
		socket.setTimeout(timeoutMs);
		socket.once('connect', () => (socket.destroy(), resolve()));
		socket.once('timeout', () => (socket.destroy(), reject(new Error('timeout'))));
		socket.once('error', (err) => (socket.destroy(), reject(err)));
	});
}

export const GET: APIRoute = async () => {
	const headers = { 'Cache-Control': 'no-store' };
	try {
		await checkDatabase();
		return Response.json({ status: 'ok' }, { headers });
	} catch {
		// OPS-002: 503 and a fixed body; never echo the error, versions, hosts or connection strings.
		return Response.json({ status: 'unavailable' }, { status: 503, headers });
	}
};

