import type { APIRoute } from 'astro';

// Prerendered at build time, so DEPLOY_ENV is read when you build: build each environment with its own
// value (import.meta.env is inlined). For one build serving every environment add
// `export const prerender = false;` and read `getSecret('DEPLOY_ENV')` from 'astro:env/server' (needs an adapter).
const production = import.meta.env.DEPLOY_ENV === 'production'; // IDX-005: the only production value

export const GET: APIRoute = ({ site }) => {
	const lines = production
		? [
				'User-agent: *',
				'Allow: /',
				// app and API paths only; never /_astro/ (Astro's JS and CSS), images or fonts (IDX-004)
				'Disallow: /api/',
				'Disallow: /account/',
				'',
				`Sitemap: ${new URL('sitemap-index.xml', site).href}` // `site` comes from astro.config
			]
		: ['User-agent: *', 'Disallow: /']; // no Sitemap line outside production
	return new Response(lines.join('\n') + '\n', { headers: { 'Content-Type': 'text/plain; charset=utf-8' } });
};

